    }

def _update_cron(self):
    """ Activate the cron job depending on whether there exists automation rules
    based on time conditions.  Also update its frequency according to
    the smallest automation delay, or restore the default 4 hours if there
    is no time based automation.
    """
    cron = self.env.ref('base_automation.ir_cron_data_base_automation_check', raise_if_not_found=False)
    if cron:
        try:
            cron.lock_for_update(allow_referencing=True)
        except LockError:
            return
        automations = self.with_context(active_test=True).search([('trigger', 'in', TIME_TRIGGERS)])
        interval_number, interval_type = self._get_cron_interval(automations)
        vals = {'active': bool(automations)}

        actual_cron_timedelta = TIMEDELTA_TYPES[cron.interval_type](cron.interval_number)
        new_cron_timedelta = TIMEDELTA_TYPES[interval_type](interval_number)
        if new_cron_timedelta < actual_cron_timedelta:
            # we only update the cron interval if the new delay is shorter than the current one
            vals.update({
                'interval_type': interval_type,
                'interval_number': interval_number,
            })
        cron.write(vals)

def _filter_post_export_domain(self, records, feedback=False):
    """ Filter the records that satisfy the postcondition of automation ``self``. """
    self_sudo = self.sudo()
    if self_sudo.filter_domain and records:
        if feedback:
            # this context flag enables to detect the executions of
            # automations while evaluating their postcondition
            records = records.with_context(__action_feedback=True)
        domain = safe_eval.safe_eval(self_sudo.filter_domain, self._get_eval_context())
        return records.sudo().filtered_domain(domain).with_env(records.env), domain
    else:
        return records, None

def _add_postmortem(self, e):
    if self.env.user._is_internal():
        e.context = {}
        e.context['exception_class'] = 'base_automation'
        e.context['base_automation'] = {
            'id': self.id,
            'name': self.sudo().name,
        }

def _check_trigger_fields(self, record):
    """ Return whether any of the trigger fields has been modified on ``record``. """
    self_sudo = self.sudo()
    if not self_sudo.trigger_field_ids:
        # all fields are implicit triggers
        return True

    if self.env.context.get('old_values') is None:
        # this is a create: all fields are considered modified
        return True

    # note: old_vals are in the record format
    old_vals = self.env.context['old_values'].get(record.id, {})

    def differ(name):
        return name in old_vals and record[name] != old_vals[name]

    return any(differ(field.name) for field in self_sudo.trigger_field_ids)

def _register_hook(self):
    """ Patch models that should trigger action rules based on creation,
        modification, deletion of records and form onchanges.
    """
    #
    # Note: the patched methods must be defined inside another function,
    # otherwise their closure may be wrong. For instance, the function
    # create refers to the outer variable 'create', which you expect to be
    # bound to create itself. But that expectation is wrong if create is
    # defined inside a loop; in that case, the variable 'create' is bound to
    # the last function defined by the loop.
    #

    def make_create():
        """ Instanciate a create method that processes automation rules. """
        @api.model_create_multi
        def create(self, vals_list, **kw):
            # retrieve the automation rules to possibly execute
            automations = self.env['base.automation']._get_actions(self, CREATE_TRIGGERS)
            if not automations:
                return create.origin(self, vals_list, **kw)
            # call original method
            records = create.origin(self.with_env(automations.env), vals_list, **kw)
            # check postconditions, and execute actions on the records that satisfy them
            for automation in automations.with_context(old_values=None):
                with _keep_to_compute(self.env, self.env._protected):
                    automation._process(automation._filter_post(records, feedback=True), trigger='create')
            return records.with_env(self.env)

        return create

    def make_write():
        """ Instanciate a write method that processes automation rules. """
        def write(self, vals, **kw):
            # retrieve the automation rules to possibly execute
            automations = self.env['base.automation']._get_actions(self, WRITE_TRIGGERS)
            if not (automations and self):
                return write.origin(self, vals, **kw)
            records = self.with_env(automations.env).filtered('id')
            written_fields = [records._fields[n] for n in vals if n in records._fields]
            # check preconditions on records
            with _keep_to_compute(self.env, written_fields):
                pre = {a: a._filter_pre(records) for a in automations}
            # read old values before the update
            old_values = {
                record.id: {field_name: record[field_name] for field_name in vals if field_name in record._fields and record._fields[field_name].store}
                for record in records
            }
            # call original method
            write.origin(self.with_env(automations.env), vals, **kw)
            # check postconditions, and execute actions on the records that satisfy them
            for automation in automations.with_context(old_values=old_values):
                with _keep_to_compute(self.env, written_fields):
                    records, domain_post = automation._filter_post_export_domain(pre[automation], feedback=True)
                    automation._process(records, domain_post=domain_post, trigger='write')
            return True

        return write

    def make_compute_field_value():
        """ Instanciate a compute_field_value method that processes automation rules. """
        #
        # Note: This is to catch updates made by field recomputations.
        #
        def _compute_field_value(self, field):
            # determine fields that may trigger an automation
            stored_fnames = [f.name for f in self.pool.field_computed[field] if f.store]
            if not stored_fnames:
                return _compute_field_value.origin(self, field)
            # retrieve the action rules to possibly execute
            automations = self.env['base.automation']._get_actions(self, WRITE_TRIGGERS)
            records = self.filtered('id').with_env(automations.env)
            if not (automations and records):
                _compute_field_value.origin(self, field)
                return True
            # check preconditions on records
            # changed fields are all fields computed by the function
            changed_fields = [f for f in records._fields.values() if f.compute == field.compute]
            with _keep_to_compute(self.env, changed_fields):
                pre = {a: a._filter_pre(records) for a in automations}
                # read old values before the update
                old_values = {
                    record.id: {fname: record[fname] for fname in stored_fnames}
                    for record in records
                }
            # call original method
            _compute_field_value.origin(self, field)
            # check postconditions, and execute automations on the records that satisfy them
            for automation in automations.with_context(old_values=old_values):
                with _keep_to_compute(self.env, changed_fields):
                    records, domain_post = automation._filter_post_export_domain(pre[automation], feedback=True)
                    automation._process(records, domain_post=domain_post, trigger='_compute_field_value')
            return True

        return _compute_field_value

    def make_unlink():
        """ Instanciate an unlink method that processes automation rules. """
        def unlink(self, **kwargs):
            # retrieve the action rules to possibly execute
            automations = self.env['base.automation']._get_actions(self, ['on_unlink'])
            records = self.with_env(automations.env)
            # check conditions, and execute actions on the records that satisfy them
            for automation in automations:
                with _keep_to_compute(self.env, self.env._protected):
                    automation._process(automation._filter_post(records, feedback=True), trigger='unlink')
            # call original method
            return unlink.origin(self, **kwargs)

        return unlink

    def make_onchange(automation_rule_id):
        """ Instanciate an onchange method for the given automation rule. """
        def base_automation_onchange(self):
            automation_rule = self.env['base.automation'].browse(automation_rule_id)

            if not automation_rule._filter_post(self):
                # Do nothing if onchange record does not satisfy the filter_domain
                return

            result = {}
            actions = automation_rule.sudo().action_server_ids.with_context(
                active_model=self._name,
                active_id=self._origin.id,
                active_ids=self._origin.ids,
                onchange_self=self,
            )
            for action in actions:
                try:
                    res = action.run()
                except Exception as e:
                    automation_rule._add_postmortem(e)
                    raise

                if res:
                    if 'value' in res:
                        res['value'].pop('id', None)
                        self.update({key: val for key, val in res['value'].items() if key in self._fields})
                    if 'domain' in res:
                        result.setdefault('domain', {}).update(res['domain'])
                    if 'warning' in res:
                        result['warning'] = res["warning"]
            return result

        return base_automation_onchange

    def make_message_post():
        def _message_post(self, *args, **kwargs):
            message = _message_post.origin(self, *args, **kwargs)
            # Don't execute automations for a message emitted during
            # the run of automations for a real message
            # Don't execute if we know already that a message is only internal
            message_sudo = message.sudo().with_context(active_test=False)
            if "__action_done"  in self.env.context or message_sudo.is_internal or message_sudo.subtype_id.internal:
                return message
            if message_sudo.message_type in ('notification', 'auto_comment', 'user_notification'):
                return message

            # always execute actions when the author is a customer
            # if author is not set, it means the message is coming from outside
            mail_trigger = "on_message_received" if not message_sudo.author_id or message_sudo.author_id.partner_share else "on_message_sent"
            automations = self.env['base.automation']._get_actions(self, [mail_trigger])
            for automation in automations.with_context(old_values=None):
                with _keep_to_compute(self.env, self.env._protected):
                    records = automation._filter_pre(self, feedback=True)
                    automation._process(records, trigger='_message_post')

            return message
        return _message_post

    patched_models = defaultdict(set)

    def patch(model, name, method):
        """ Patch method `name` on `model`, unless it has been patched already. """
        if model not in patched_models[name]:
            patched_models[name].add(model)
            ModelClass = model.env.registry[model._name]
            method.origin = getattr(ModelClass, name)
            setattr(ModelClass, name, method)

    # retrieve all actions, and patch their corresponding model
    for automation_rule in self.with_context({}).search([]):
        Model = self.env.get(automation_rule.model_name)

        # Do not crash if the model of the base_action_rule was uninstalled
        if Model is None:
            _logger.warning(
                "Automation rule with name '%s' (ID %d) depends on model %s (ID: %d)",
                automation_rule.name,
                automation_rule.id,
                automation_rule.model_name,
                automation_rule.model_id.id)
            continue

        if automation_rule.trigger in CREATE_WRITE_SET:
            if automation_rule.trigger in CREATE_TRIGGERS:
                patch(Model, 'create', make_create())
            if automation_rule.trigger in WRITE_TRIGGERS:
                patch(Model, 'write', make_write())
                patch(Model, '_compute_field_value', make_compute_field_value())

        elif automation_rule.trigger == 'on_unlink':
            patch(Model, 'unlink', make_unlink())

        elif automation_rule.trigger == 'on_change':
            # register an onchange method for the automation_rule
            method = make_onchange(automation_rule.id)
            for field in automation_rule.on_change_field_ids:
                Model._onchange_methods[field.name].append(method)

        if automation_rule.model_id.is_mail_thread and automation_rule.trigger in MAIL_TRIGGERS:
            patch(Model, "message_post", make_message_post())

def _unregister_hook(self):
    """ Remove the patches installed by _register_hook() """
    NAMES = ['create', 'write', '_compute_field_value', 'unlink', '_onchange_methods', "message_post"]
    for Model in self.env.registry.values():
        for name in NAMES:
            try:
                delattr(Model, name)
            except AttributeError:
                pass

def _check(self, automatic=False, use_new_cursor=False):
    if not automatic:
        raise RuntimeError("can run time-based automations only in automatic mode")
    self._cron_process_time_based_actions()

def _search_time_based_automation_records(self, *, until):
    automation = self.ensure_one()

    # retrieve the domain and field
    domain = Domain.TRUE
    if automation.filter_domain:
        eval_context = automation._get_eval_context()
        domain = Domain(safe_eval.safe_eval(automation.filter_domain, eval_context))
    Model = self.env[automation.model_name]
    date_field = Model._fields.get(automation.trg_date_id.name)
    if not date_field:
        _logger.warning("Missing date trigger field in automation rule `%s`", automation.name)
        return Model

    # get the time information and find the records
    last_run = automation.last_run or datetime.datetime.fromtimestamp(0, tz=None)
    is_date_automation_last = date_field.name == "date_automation_last" and "create_date" in Model._fields
    range_sign = 1 if automation.trg_date_range_mode == 'before' else -1
    date_range = range_sign * automation.trg_date_range

    def get_record_dt(record):
        # the field can be a date or datetime, cast always to a datetime
        dt = record[date_field.name]
        if not dt and is_date_automation_last:
            dt = record.create_date
        return fields.Datetime.to_datetime(dt)

    if automation.trg_date_calendar_id and automation.trg_date_range_type == 'day':
        # use the calendar information from the record
        # _get_calendar can be overwritten and cannot be optimized
        time_domain = Domain.TRUE if is_date_automation_last else Domain(date_field.name, '!=', False)
        if date_field._description_searchable:
            records = Model.search(time_domain & domain)
        else:
            records = Model.search(domain).filtered_domain(time_domain)

        past_until = {}
        past_last_run = {}

        def calendar_filter(record):
            record_dt = get_record_dt(record)
            if not record_dt:
                return False
            calendar = self._get_calendar(automation, record)
            if calendar.id not in past_until:
                past_until[calendar.id] = calendar.plan_days(
                    date_range,
                    until,
                    compute_leaves=True,
                )
                past_last_run[calendar.id] = calendar.plan_days(
                    date_range,
                    last_run,
                    compute_leaves=True,
                )
            return (
                past_last_run[calendar.id]
                and past_until[calendar.id]
                and past_last_run[calendar.id] <= record_dt < past_until[calendar.id]
            )

        return records.filtered(calendar_filter)

    # we can search for the records to trigger
    # find the relative dates
    relative_offset = DATE_RANGE[automation.trg_date_range_type] * date_range
    relative_until = until + relative_offset
    relative_last_run = last_run + relative_offset
    if date_field.type == 'date':
        # find records that have a date in past, but were not yet executed that day
        time_domain = Domain(date_field.name, '>', relative_last_run.date()) & Domain(date_field.name, '<=', relative_until.date())
        if is_date_automation_last:
            time_domain |= Domain(date_field.name, '=', False) & Domain('create_date', '>', relative_last_run.date()) & Domain('create_date', '<=', relative_until.today())
    else:  # datetime
        time_domain = Domain(date_field.name, '>=', relative_last_run) & Domain(date_field.name, '<', relative_until)
        if is_date_automation_last:
            time_domain |= Domain(date_field.name, '=', False) & Domain('create_date', '>=', relative_last_run) & Domain('create_date', '<', relative_until)

    if date_field._description_searchable:
        return Model.search(time_domain & domain)
    else:
        return Model.search(domain).filtered_domain(time_domain)

def _cron_process_time_based_actions(self):
    """ Execute the time-based automations. """
    if '__action_done' not in self.env.context:
        self = self.with_context(__action_done={})

    # retrieve all the automation rules to run based on a timed condition
    final_exception = None
    automations = self.with_context(active_test=True).search([('trigger', 'in', TIME_TRIGGERS)])

    for automation in automations:
        automation = automation.with_prefetch()
        # is automation deactivated or disappeared between commits?
        try:
            if not automation.active:
                continue
        except MissingError:
            continue
        _logger.info("Starting time-based automation rule `%s`.", automation.name)
        now = self.env.cr.now()
        records = automation._search_time_based_automation_records(until=now)
        # run the automation on the records
        record = None
        try:
            for record in records:
                automation._process(record, trigger='time-based')
            record = None  # a flush error can't be attributed to a record
            self.env.flush_all()
        except Exception as e:
            self.env['ir.cron']._rollback_progress()
            if record:
                _logger.exception("Error in time-based automation rule `%s` on record %s.", automation.name, record)
            else:
                _logger.exception("Error in time-based automation rule `%s`.", automation.name)
            final_exception = e
            continue

        automation.write({'last_run': now})
        _logger.info("Time-based automation rule `%s` done.", automation.name)
        self.env['ir.cron']._commit_progress()
    if final_exception is not None:
        # raise the last found exception to mark the cron job as failing
        raise final_exception

@Override
@Transactional
public void generateTasks(ProjectTask projectTask, Frequency frequency) {
  List<LocalDate> taskDateList =
      frequencyService.getDates(frequency, projectTask.getTaskDate(), frequency.getEndDate());

  taskDateList.removeIf(date -> date.equals(projectTask.getTaskDate()));

  // limit how many ProjectTask will be generated at once
  Integer limitNumberTasksGenerated = appBaseService.getAppBase().getLimitNumberTasksGenerated();
  if (taskDateList.size() > limitNumberTasksGenerated) {
    taskDateList = taskDateList.subList(0, limitNumberTasksGenerated);
  }

  ProjectTask lastTask = projectTask;
  for (LocalDate date : taskDateList) {
    ProjectTask newProjectTask = projectTaskRepo.copy(projectTask, false);
    setModuleFields(projectTask, date, newProjectTask);
    projectTaskRepo.save(newProjectTask);

    lastTask.setNextProjectTask(newProjectTask);
    projectTaskRepo.save(lastTask);
    lastTask = newProjectTask;
  }
}

@Override
@Transactional
public void updateNextTask(ProjectTask projectTask) {
  ProjectTask nextProjectTask = projectTask.getNextProjectTask();
  if (nextProjectTask != null) {
    updateModuleFields(projectTask, nextProjectTask);

    projectTaskRepo.save(nextProjectTask);
    updateNextTask(nextProjectTask);
  }
}

protected void updateModuleFields(ProjectTask projectTask, ProjectTask nextProjectTask) {
  nextProjectTask.setName(projectTask.getName());
  nextProjectTask.setPriority(projectTask.getPriority());
  nextProjectTask.setStatus(projectTask.getStatus());
  nextProjectTask.setTaskDuration(projectTask.getTaskDuration());
  nextProjectTask.setAssignedTo(projectTask.getAssignedTo());
  nextProjectTask.setDescription(projectTask.getDescription());

  nextProjectTask.setFullName(projectTask.getFullName());
  nextProjectTask.setProject(projectTask.getProject());
  nextProjectTask.setProjectTaskCategory(projectTask.getProjectTaskCategory());
  nextProjectTask.setProgress(BigDecimal.ZERO);

  projectTask.getMembersUserSet().forEach(nextProjectTask::addMembersUserSetItem);

  nextProjectTask.setParentTask(projectTask.getParentTask());
  nextProjectTask.setProduct(projectTask.getProduct());
  nextProjectTask.setInvoicingUnit(projectTask.getInvoicingUnit());
  nextProjectTask.setQuantity(projectTask.getQuantity());
  nextProjectTask.setUnitPrice(projectTask.getUnitPrice());
  nextProjectTask.setTaskEndDate(projectTask.getTaskEndDate());
  nextProjectTask.setBudgetedTime(projectTask.getBudgetedTime());
  nextProjectTask.setCurrency(projectTask.getCurrency());
}

@Override
@Transactional
public void removeNextTasks(ProjectTask projectTask) {
  List<ProjectTask> projectTaskList = getAllNextTasks(projectTask);
  projectTask.setNextProjectTask(null);
  projectTask.setHasDateOrFrequencyChanged(false);
  projectTaskRepo.save(projectTask);

  for (ProjectTask projectTaskToRemove : projectTaskList) {
    projectTaskRepo.remove(projectTaskToRemove);
  }
}

public List<ProjectTask> getAllNextTasks(ProjectTask projectTask) {
  List<ProjectTask> projectTaskList = new ArrayList<>();

  ProjectTask current = projectTask;
  while (current.getNextProjectTask() != null) {
    current = current.getNextProjectTask();
    projectTaskList.add(current);
  }

  for (ProjectTask task : projectTaskList) {
    task.setNextProjectTask(null);
    projectTaskRepo.save(task);
  }

  return projectTaskList;
}

@Override
@Transactional
public ProjectTask create(String subject, Project project, User assignedTo) {
  ProjectTask task = new ProjectTask();
  task.setName(subject);
  task.setAssignedTo(assignedTo);
  task.setTaskDate(appBaseService.getTodayDate(null));
  task.setStatus(getStatus(project, task));
  task.setPriority(getPriority(project));
  project.addProjectTaskListItem(task);
  projectTaskRepo.save(task);
  return task;
}

protected void setModuleFields(
    ProjectTask projectTask, LocalDate date, ProjectTask newProjectTask) {

  newProjectTask.setIsFirst(false);
  newProjectTask.setHasDateOrFrequencyChanged(false);
  newProjectTask.setDoApplyToAllNextTasks(false);
  newProjectTask.setFrequency(frequencyRepo.copy(projectTask.getFrequency(), false));
  newProjectTask.setTaskDate(date);
  newProjectTask.setTaskDeadline(date);
  newProjectTask.setNextProjectTask(null);
  // Module 'project' fields
  newProjectTask.setProgress(BigDecimal.ZERO);
  newProjectTask.setTaskEndDate(date);
}

@Override
public TaskStatus getStatus(Project project, ProjectTask projectTask) {
  if (project == null) {
    return null;
  }

  project = projectRepository.find(project.getId());
  Set<TaskStatus> projectStatusSet = taskStatusToolService.getTaskStatusSet(project, projectTask);

  return ObjectUtils.isEmpty(projectStatusSet)
      ? null
      : projectStatusSet.stream()
          .min(Comparator.comparingInt(TaskStatus::getSequence))
          .orElse(null);
}

@Override
public ProjectPriority getPriority(Project project) {
  if (project == null) {
    return null;
  }

  project = projectRepository.find(project.getId());

  return ObjectUtils.isEmpty(project.getProjectTaskPrioritySet())
      ? null
      : project.getProjectTaskPrioritySet().stream()
          .filter(
              priority ->
                  priority.getTechnicalTypeSelect()
                      == ProjectPriorityRepository.PROJECT_PRIORITY_NORMAL)
          .findAny()
          .orElse(null);
}

@Transactional
public void deleteProjectTask(ProjectTask projectTask) {
  new SecurityCheck().removeAccess(ProjectTask.class, projectTask.getId()).check();
  projectTaskRepo.remove(projectTask);
}

@Override
public void deleteProjectTasks(List<Integer> projectTasksIds) {
  if (ObjectUtils.isEmpty(projectTasksIds)) {
    return;
  }

  for (Integer id : projectTasksIds) {
    deleteProjectTask(projectTaskRepo.find(Long.valueOf(id)));
  }
}

@Override
public String getTaskLink(String value) {
  if (StringUtils.isEmpty(value)) {
    return value;
  }
  StringBuffer buffer = new StringBuffer();
  Matcher matcher = Pattern.compile("@([^\\s]+)").matcher(value);
  Matcher nonMatcher = Pattern.compile("@([^\\s]+)(?=<\\/a>)").matcher(value);
  while (matcher.find()) {
    String matchedValue = matcher.group(1);
    String ticketNumber = matchedValue.replaceAll("\\<.*?\\>", "");
    if (nonMatcher.find() && ticketNumber.equals(nonMatcher.group(1))) {
      continue;
    }
    ProjectTask task =
        projectTaskRepo.all().filter("self.ticketNumber = ?1", ticketNumber).fetchOne();
    if (task != null) {
      matcher.appendReplacement(buffer, String.format(TASK_LINK, task.getId(), matchedValue));
    }
  }

  String result = buffer.toString();
  return StringUtils.isEmpty(result) ? value : result;
}

@Override
public void fillSubtask(ProjectTask projectTask) {
  ProjectTask parentTask = projectTaskRepo.find(projectTask.getParentTask().getId());
  projectTask.setParentTask(parentTask);
  projectTask.setProjectTaskCategory(parentTask.getProjectTaskCategory());
  projectTask.setPriority(parentTask.getPriority());
  projectTask.setTagSet(parentTask.getTagSet());
  projectTask.setAssignedTo(parentTask.getAssignedTo());
  projectTask.setTargetVersion(projectTask.getParentTask().getTargetVersion());
}

@Override
public void changeProgress(ProjectTask projectTask, Project project) {
  if (projectTask == null) {
    return;
  }

  projectTask.setProgress(getNewProgress(projectTask, project));
}

protected BigDecimal getNewProgress(ProjectTask projectTask, Project project) {
  AppProject appProject = appProjectService.getAppProject();
  if (appProject != null
      && appProject.getSelectAutoProgressOnProjectTask()
      && projectTask.getStatus() != null) {
    BigDecimal newProgress = projectTask.getStatus().getDefaultProgress();
    if (appProject.getEnableStatusManagementByTaskCategory()
        && project != null
        && project.getEnableStatusProgressByCategory()
        && projectTask.getProjectTaskCategory() != null) {
      TaskStatusProgressByCategory taskStatusProgressByCategory =
          taskStatusProgressByCategoryRepository.findByCategoryAndStatus(
              projectTask.getProjectTaskCategory(), projectTask.getStatus());
      if (taskStatusProgressByCategory != null) {
        newProgress = taskStatusProgressByCategory.getProgress();
      }
    }

    return newProgress;
  }

  return projectTask.getProgress();
}

@Override
@Transactional
public void computeProjectTaskLevels(Project project) {
  List<ProjectTask> projectTaskList =
      project.getProjectTaskList().stream()
          .filter(task -> task.getParentTask() == null)
          .collect(Collectors.toList());
  computeLevels(projectTaskList, null);
}

protected void computeLevels(List<ProjectTask> projectTaskList, String parentLevel) {
  if (CollectionUtils.isEmpty(projectTaskList)) {
    return;
  }
  projectTaskList.sort(
      Comparator.comparing(
          ProjectTask::getCreatedOn, Comparator.nullsLast(Comparator.naturalOrder())));
  int count = 1;
  for (ProjectTask projectTask : projectTaskList) {
    String levelIndicator =
        StringUtils.isBlank(parentLevel)
            ? String.valueOf(count)
            : String.format("%s.%s", parentLevel, count);
    projectTask.setLevelIndicator(levelIndicator);
    count++;
    computeLevels(projectTask.getProjectTaskList(), levelIndicator);
  }
}

@Override
@Transactional
public StockLocationLineHistory saveHistory(
    StockLocationLine stockLocationLine, LocalDateTime dateTime, String origin, String typeSelect)
    throws AxelorException {
  Product product = stockLocationLine.getProduct();
  Company company = stockLocationLine.getStockLocation().getCompany();
  return stockLocationLineHistoryRepo.save(
      new StockLocationLineHistory(
          stockLocationLine,
          typeSelect,
          dateTime,
          origin,
          stockLocationLine.getAvgPrice(),
          stockLocationLine.getCurrentQty(),
          stockLocationLine.getUnit(),
          (BigDecimal) productCompanyService.get(product, "salePrice", company),
          (BigDecimal) productCompanyService.get(product, "purchasePrice", company),
          (BigDecimal) productCompanyService.get(product, "costPrice", company)));
}

@Override
public List<StockLocationLineHistory> getStockLineHistoryLines(
    StockLocationLine stockLocationLine) {

  return stockLocationLineHistoryRepo
      .all()
      .filter("self.stockLocationLine = :stockLocationLine")
      .bind("stockLocationLine", stockLocationLine)
      .fetch();
}
